import sqlite3,re,json
p='/home/USER/continual-arc-baselines/.workbench/stage1/H0-hermes-luna6-medium-ws0/frozen/held-out/play/users/u027/system/state/hermes/state.db'
c=sqlite3.connect(p); sid='60b667f9-030b-4f09-8bf9-ef3e08936ee3'
u=c.execute('select content from messages where session_id=? and id=1',(sid,)).fetchone()[0]
block=u.split('Test input (23x25):\n')[1].split('\nWrong attempts')[0]
g=[list(map(int,re.findall(r'\d+',r))) for r in block.splitlines()]
a=json.loads(c.execute('select content from messages where session_id=? and id=135',(sid,)).fetchone()[0]); out=a['grid']
print('input/output dims',len(g),set(map(len,g)),len(out),set(map(len,out)))
lines={(r,col) for r in (4,11) for col in range(25)}|{(r,5) for r in range(23)}
def solve(diag=False):
 seen=set(); comps=[]
 for r in range(23):
  for col in range(25):
   if g[r][col]!=2 or (r,col) in seen: continue
   q=[(r,col)]; seen.add((r,col)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      if (not diag and abs(dy)+abs(dx)!=1) or (diag and dy==dx==0): continue
      ny,nx=y+dy,x+dx
      if 0<=ny<23 and 0<=nx<25 and g[ny][nx]==2 and (ny,nx) not in seen: seen.add((ny,nx));q.append((ny,nx))
   comps.append(comp)
 z=[row[:] for row in g]
 for comp in comps:
  if any(p in lines for p in comp):
   for y,x in comp:z[y][x]=1
 for y,x in lines:z[y][x]=1
 return z
for diag in (False,True):
 e=solve(diag); dif=[(r,col,e[r][col],out[r][col]) for r in range(23) for col in range(25) if e[r][col]!=out[r][col]]
 print('diagonal_connectivity',diag,'diff count',len(dif),'first diffs',dif[:30])

